/**
 * Dense linear algebra helpers: LU solve and stationary-distribution extraction.
 *
 * These are required by the Markov-chain routines (passage_time, markov_stability)
 * that rely on the Kemeny-Snell identity (I - P + 1·pi^T)^{-1}.
 *
 * Only dense, small-matrix workloads (typical Markov networks have 3..50 states),
 * so a Gaussian elimination with partial pivoting is sufficient.
 */
import { Matrix } from './matrix.js';

/**
 * Solve a linear system A·x = b via LU decomposition with partial pivoting.
 *
 * Matches the behaviour of R's `base::solve(A, b)` for well-conditioned systems.
 * Throws on singular or near-singular matrices; the caller is responsible for
 * pre-checking ergodicity when passing a Markov-derived matrix.
 *
 * @param A square n×n matrix (must be non-singular).
 * @param b right-hand side; either an n-vector or an n×m matrix.
 * @returns solution x (same shape as b).
 */
export function solveLinear(A: Matrix, b: Matrix | Float64Array | number[]): Matrix {
  if (!A.isSquare) {
    throw new Error('solveLinear: A must be square');
  }
  const n = A.rows;

  // Normalise b to Matrix form (n × m)
  let B: Matrix;
  if (b instanceof Matrix) {
    if (b.rows !== n) {
      throw new Error(`solveLinear: rhs rows ${b.rows} != A rows ${n}`);
    }
    B = b.clone();
  } else {
    if (b.length !== n) {
      throw new Error(`solveLinear: rhs length ${b.length} != A rows ${n}`);
    }
    B = new Matrix(n, 1);
    for (let i = 0; i < n; i++) B.set(i, 0, b[i]!);
  }
  const m = B.cols;

  // Work on copies; perform in-place PA = LU with partial pivoting.
  const LU = A.clone();
  const RHS = B;

  for (let k = 0; k < n; k++) {
    // Partial pivot: find max |LU[i,k]| for i ≥ k
    let pivot = Math.abs(LU.get(k, k));
    let pivotRow = k;
    for (let i = k + 1; i < n; i++) {
      const v = Math.abs(LU.get(i, k));
      if (v > pivot) {
        pivot = v;
        pivotRow = i;
      }
    }

    if (pivot < 1e-14) {
      throw new Error(
        `solveLinear: matrix is singular or near-singular (pivot ${pivot} at col ${k})`,
      );
    }

    // Swap rows in LU and RHS
    if (pivotRow !== k) {
      for (let j = 0; j < n; j++) {
        const tmp = LU.get(k, j);
        LU.set(k, j, LU.get(pivotRow, j));
        LU.set(pivotRow, j, tmp);
      }
      for (let j = 0; j < m; j++) {
        const tmp = RHS.get(k, j);
        RHS.set(k, j, RHS.get(pivotRow, j));
        RHS.set(pivotRow, j, tmp);
      }
    }

    // Eliminate below pivot
    const pivotVal = LU.get(k, k);
    for (let i = k + 1; i < n; i++) {
      const factor = LU.get(i, k) / pivotVal;
      if (factor !== 0) {
        LU.set(i, k, factor); // store multiplier (not strictly needed for solve-only)
        for (let j = k + 1; j < n; j++) {
          LU.set(i, j, LU.get(i, j) - factor * LU.get(k, j));
        }
        for (let j = 0; j < m; j++) {
          RHS.set(i, j, RHS.get(i, j) - factor * RHS.get(k, j));
        }
      }
    }
  }

  // Back-substitute: U x = RHS
  const X = new Matrix(n, m);
  for (let j = 0; j < m; j++) {
    for (let i = n - 1; i >= 0; i--) {
      let sum = RHS.get(i, j);
      for (let k = i + 1; k < n; k++) {
        sum -= LU.get(i, k) * X.get(k, j);
      }
      X.set(i, j, sum / LU.get(i, i));
    }
  }
  return X;
}

/**
 * Compute the stationary distribution π of a row-stochastic matrix P.
 *
 * Equivalent to R's `.mpt_stationary`: eigen-decompose Pᵀ, pick the eigenvector
 * whose eigenvalue is closest to 1, take |Re(·)|, normalise to sum 1.
 *
 * Because we do not ship a full complex-eigen routine, we use inverse iteration:
 * solve (Pᵀ - I + ε·I)·v = v₀ repeatedly, which converges to the eigenvector
 * associated with the eigenvalue 1. For ergodic row-stochastic P this matches
 * R's `abs(Re(eigen(t(P))$vectors[, idx]))` up to sign/normalisation.
 *
 * As a robustness fallback we also check via power iteration on Pᵀ shifted so
 * that the dominant eigenvalue is unique (the actual computation uses a linear
 * solve of (I - Pᵀ + 1·1ᵀ/n)·π = 1/n which gives π in one shot for ergodic P —
 * a known closed-form trick equivalent to solving πᵀ P = πᵀ, Σπ = 1).
 *
 * @throws if P has a zero row (non-ergodic).
 */
export function eigenDominantLeft(P: Matrix): Float64Array {
  if (!P.isSquare) {
    throw new Error('eigenDominantLeft: P must be square');
  }
  const n = P.rows;

  // Sanity: row sums must be positive (caller should pre-validate ergodicity).
  const rowSums = P.rowSums();
  for (let i = 0; i < n; i++) {
    if (rowSums[i]! <= 0) {
      throw new Error(
        `eigenDominantLeft: row ${i} has sum ${rowSums[i]} — chain is not ergodic`,
      );
    }
  }

  // Closed form: π solves (I - Pᵀ + (1/n)·J)·π = (1/n)·1.
  // Proof: replace one of the redundant equations (Pᵀ - I)π = 0 with Σπᵢ = 1.
  // Adding (1/n)·J (matrix of 1s) to (I - Pᵀ) maps the kernel to 1/n·1, so the
  // normalised stationary solution falls out of a single linear solve. This is
  // numerically equivalent to R's eigen-based approach for ergodic P.
  const A = new Matrix(n, n);
  const invN = 1 / n;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      let a = i === j ? 1 : 0;
      a -= P.get(j, i); // transpose: Pᵀ[i,j] = P[j,i]
      a += invN;
      A.set(i, j, a);
    }
  }
  const rhs = new Float64Array(n);
  for (let i = 0; i < n; i++) rhs[i] = invN;

  const sol = solveLinear(A, rhs);
  const pi = new Float64Array(n);
  let sum = 0;
  for (let i = 0; i < n; i++) {
    const v = Math.abs(sol.get(i, 0));
    pi[i] = v;
    sum += v;
  }
  if (sum === 0) {
    throw new Error('eigenDominantLeft: stationary vector collapsed to zero');
  }
  for (let i = 0; i < n; i++) pi[i]! /= sum;
  return pi;
}
