/**
 * prepareLong — the long event-log → wide sequences pivot, WITH metadata.
 *
 * This is the engine's counterpart to R `tna::prepare_data(data, actor, time, action, order,
 * time_threshold, unused_fn)`, and it exists because the function did not exist here and so
 * got written four times:
 *
 *   · Dynalytics_Desktop/src/data.ts   — longToSequences + extractCovariatesPerSequence
 *   · carm-tna's built notebook        — "verbatim copy of Dynalytics longToSequences logic"
 *   · carmnote-htna-pro/lib/model.js   — extractLongRows + cutSessionsOnGap + sessionValues
 *   · R tna::prepare_data              — the original
 *
 * Four copies, and they had drifted at exactly the seams nobody compared: whether a 0/1 flag
 * counts as numeric (so whether it may enter a covariate model at all), how a repeated column
 * is collapsed onto a session, and where a session is cut. One implementation, pinned to R.
 *
 * WHAT METADATA IS. Everything the pivot did not consume, one row per SESSION. Not a rule
 * invented here: R takes `wide_data[, !(sequence_cols | time_cols)]` — so the ACTOR and the
 * raw TIME column survive as metadata too (time collapses to the session's start), and only
 * the action columns (which became T1..Tn) are removed. A column that would otherwise be
 * repeated across a session's events is collapsed by an aggregator.
 *
 * WHY IT AGGREGATES RATHER THAN REFUSES. R's default is `unused_fn = dplyr::first` — take the
 * first value, silently. Dynalytics is type-aware (`numericAgg: 'mean'`, `categoricalAgg:
 * 'mode'`). Both are defensible; neither tells you when the column was NOT constant, which is
 * the case where the aggregation actually changes the answer. So we aggregate like Dynalytics
 * AND report every column that varied within a session, in `meta.varying`. The caller can then
 * refuse it, mean it, or shrug — but never without knowing.
 */

/** How a repeated column is collapsed onto one session. */
export type NumericAgg = 'first' | 'last' | 'sum' | 'mean' | 'mode';
export type CategoricalAgg = 'first' | 'last' | 'mode';

export interface PrepareLongOptions {
  /** Column name (or index) identifying the actor/participant. Required. */
  actor: string | number;
  /** The event/state column that becomes the sequence. Required. */
  action: string | number;
  /** Timestamp column. Used for ordering and for session cutting. */
  time?: string | number;
  /** Explicit ordering column, used when `time` is absent or ties. */
  order?: string | number;
  /**
   * Cut a session after this much inactivity, in the units of `time`.
   * R `prepare_data(time_threshold = 900)`. 0 / undefined = never cut.
   */
  timeThreshold?: number;
  /** Collapse rule for a numeric metadata column. Default 'mean' (Dynalytics). */
  numericAgg?: NumericAgg;
  /** Collapse rule for a categorical metadata column. Default 'mode' (Dynalytics). */
  categoricalAgg?: CategoricalAgg;
}

export interface MetaData {
  /** Column names, in dataset order. `.session_id` and `.session_nr` lead, as in R. */
  columns: string[];
  /** One row per SEQUENCE, index-aligned with `sequences`. */
  rows: (string | number | null)[][];
  /** Per column: is it a measurement or a factor? */
  types: ('numeric' | 'categorical')[];
  /**
   * Columns that were NOT constant within at least one session, and how many sessions.
   * The aggregator silently produced a number for these; whether that number MEANS anything
   * is the caller's call, and it cannot make it without being told.
   */
  varying: { column: string; nSessions: number }[];
}

export interface PrepareLongResult {
  /** Wide, ragged sequences — one array per session, in session order. */
  sequences: (string | null)[][];
  /** Session ids, R's format: `<actor> session<N>`. Index-aligned with `sequences`. */
  ids: string[];
  /** The actor each session belongs to (a session is nested in an actor; the tests that
   *  follow usually assume independent rows, and this is what lets a caller notice). */
  actors: string[];
  /** 1-based session number WITHIN the actor (R `.session_nr`). */
  sessionNr: number[];
  /** The RAW ROW INDICES that produced each session, in order. The exact join key for any
   *  per-session quantity: a session id is not always a value in the data (a gap cut mints
   *  `u1 session2`), so joining by id works right up until someone sets a time threshold. */
  seqRowIndices: number[][];
  /** Parsed, sorted time values per session (empty when no time column). */
  times: number[][];
  meta: MetaData;
  statistics: {
    totalSessions: number;
    totalActions: number;
    maxSequenceLength: number;
    meanSequenceLength: number;
    uniqueActors: number;
    /** Sessions per actor — > 1 anywhere means sessions are NESTED and the usual
     *  independence assumption of every downstream test is violated. */
    sessionsPerActor: { actor: string; nSessions: number }[];
    actionsPerSession: { id: string; nActions: number }[];
    /** Sessions created by cutting on `timeThreshold` (0 when nothing was cut). */
    sessionsFromGap: number;
  };
}

/** A timestamp as a sortable number: a plain number, else a parsed date. null when neither. */
export function parseTimeValue(raw: unknown): number | null {
  if (raw == null || raw === '') return null;
  const n = Number(raw);
  if (!Number.isNaN(n) && Number.isFinite(n)) return n;
  const d = new Date(String(raw));
  const t = d.getTime();
  return Number.isNaN(t) ? null : t;
}

function mode(vals: string[]): string {
  const freq = new Map<string, number>();
  for (const v of vals) freq.set(v, (freq.get(v) ?? 0) + 1);
  let best = vals[0]!, bestN = 0;
  for (const [v, n] of freq) if (n > bestN) { best = v; bestN = n; }
  return best;
}

/**
 * Is this column a measurement or a factor?
 *
 * "Every non-blank value parses as a finite number" — and NOTHING else. Dynalytics uses
 * exactly this; carmnote had added "…and more than 2 distinct values", which quietly
 * reclassified every 0/1 indicator as a factor and so barred it from entering a covariate
 * model at all. A binary flag is a perfectly good regressor; the extra clause was a guess at
 * the user's intent that guessed wrong.
 */
export function isNumericColumn(vals: readonly string[]): boolean {
  const seen = vals.filter((v) => v != null && v !== '');
  if (seen.length === 0) return false;
  return seen.every((v) => Number.isFinite(Number(v)));
}

/**
 * Collapse one session's values for one column.
 *
 * `vals` arrives RAW, blanks included, because the two families of aggregator need different
 * things from a blank:
 *
 *   POSITIONAL ('first', 'last') name a ROW, so they return that row's value even when it is
 *   blank — exactly as R's `dplyr::first`, which returns NA for `c(NA, 1.3, 2)`. Reaching past
 *   the blank to the next row would not collapse the column, it would IMPUTE it: a session
 *   whose covariate is genuinely missing would acquire a neighbouring row's number and slip
 *   into models that drop missing rows on purpose. Missingness has to survive.
 *
 *   SUMMARY ('mean', 'sum', 'mode') are over the values that exist, so they skip blanks — you
 *   do not average a blank. If nothing exists, the answer is blank, not 0. (`Number('')` is 0,
 *   which is how a missing covariate becomes a confident zero.)
 */
function aggregate(vals: string[], numericAgg: NumericAgg, categoricalAgg: CategoricalAgg): string {
  if (vals.length === 0) return '';
  const first = vals[0]!;
  const last = vals[vals.length - 1]!;
  const present = vals.filter((v) => v !== '');

  if (isNumericColumn(vals)) {
    switch (numericAgg) {
      case 'first': return first;
      case 'last': return last;
      case 'mode': return present.length ? mode(present) : '';
      case 'sum':
      default: {
        if (present.length === 0) return '';
        const nums = present.map(Number);
        const total = nums.reduce((a, b) => a + b, 0);
        return String(numericAgg === 'sum' ? total : total / nums.length);
      }
    }
  }
  switch (categoricalAgg) {
    case 'first': return first;
    case 'last': return last;
    default: return present.length ? mode(present) : '';
  }
}

/**
 * Long event log → wide sequences + metadata.
 *
 * @param rows    raw data rows (arrays of cells, in `headers` order)
 * @param headers column names
 */
export function prepareLong(
  rows: readonly (readonly unknown[])[],
  headers: readonly string[],
  options: PrepareLongOptions,
): PrepareLongResult {
  const colIdx = (c: string | number | undefined): number => {
    if (c == null) return -1;
    if (typeof c === 'number') return c;
    return headers.indexOf(c);
  };
  const actorI = colIdx(options.actor);
  const actionI = colIdx(options.action);
  const timeI = colIdx(options.time);
  const orderI = colIdx(options.order);
  if (actorI < 0) throw new Error('prepareLong: actor column not found');
  if (actionI < 0) throw new Error('prepareLong: action column not found');

  const numericAgg = options.numericAgg ?? 'mean';
  const categoricalAgg = options.categoricalAgg ?? 'mode';
  const threshold = options.timeThreshold ?? 0;

  const cell = (r: readonly unknown[], i: number): string =>
    (i < 0 || r[i] == null ? '' : String(r[i]).trim());

  // ── group the raw rows by actor, keeping their ORIGINAL index ──────────────
  interface Ev { row: number; t: number | null; ord: number | null }
  const byActor = new Map<string, Ev[]>();
  const actorOrder: string[] = [];
  rows.forEach((r, i) => {
    const act = cell(r, actionI);
    if (act === '') return;                       // an empty event is not an event
    const a = cell(r, actorI);
    if (a === '') return;
    if (!byActor.has(a)) { byActor.set(a, []); actorOrder.push(a); }
    byActor.get(a)!.push({
      row: i,
      t: timeI >= 0 ? parseTimeValue(r[timeI]) : null,
      ord: orderI >= 0 ? parseTimeValue(r[orderI]) : null,
    });
  });

  // ── order within actor, then CUT on inactivity ────────────────────────────
  // R cuts inside prepare_data, before anything else sees the data, and names the parts
  // `<actor> session1`, `<actor> session2`. Matching the NAME matters: it is what a user
  // reads in every downstream table.
  const ids: string[] = [];
  const actors: string[] = [];
  const sessionNr: number[] = [];
  const seqRowIndices: number[][] = [];
  const times: number[][] = [];
  let sessionsFromGap = 0;

  for (const a of actorOrder) {
    const evs = byActor.get(a)!;
    evs.sort((x, y) => {
      // time first, then explicit order, then original row order — a stable, total order.
      if (x.t != null && y.t != null && x.t !== y.t) return x.t - y.t;
      if (x.ord != null && y.ord != null && x.ord !== y.ord) return x.ord - y.ord;
      return x.row - y.row;
    });

    let part: Ev[] = [];
    const parts: Ev[][] = [];
    for (let i = 0; i < evs.length; i++) {
      const e = evs[i]!;
      if (part.length > 0 && threshold > 0 && e.t != null) {
        const prev = part[part.length - 1]!.t;
        if (prev != null && e.t - prev > threshold) {
          parts.push(part);
          part = [];
          sessionsFromGap++;
        }
      }
      part.push(e);
    }
    if (part.length) parts.push(part);

    parts.forEach((p, k) => {
      ids.push(a + ' session' + (k + 1));
      actors.push(a);
      sessionNr.push(k + 1);
      seqRowIndices.push(p.map((e) => e.row));
      times.push(p.map((e) => e.t).filter((t): t is number => t != null));
    });
  }

  // ── the sequences ─────────────────────────────────────────────────────────
  const sequences: (string | null)[][] = seqRowIndices.map((idxs) =>
    idxs.map((i) => cell(rows[i]!, actionI)));

  // ── METADATA: everything the pivot did not consume, one row per session ───
  // R removes only the ACTION columns (they became T1..Tn) and the standardized-time
  // columns — so the actor and the raw time column SURVIVE as metadata, time collapsing to
  // the session's start. Excluding them (as carmnote did) throws away the session start time
  // and the actor key, both of which a caller legitimately wants.
  const metaCols: number[] = headers.map((_, i) => i).filter((i) => i !== actionI);
  // R's column ORDER: .session_id, then the data columns, then .session_nr LAST. Matching it
  // is not pedantry — a caller that indexes meta by position (and designMatrix does) would
  // otherwise silently read the wrong column.
  const columns = ['.session_id', ...metaCols.map((i) => headers[i]!), '.session_nr'];

  const varying: { column: string; nSessions: number }[] = [];
  const perCol: string[][] = metaCols.map(() => []);
  metaCols.forEach((ci, c) => {
    // THE TIME COLUMN IS NOT JUST ANOTHER NUMERIC COLUMN. It always collapses to `first` —
    // the session's START time — whatever `numericAgg` says. Dynalytics' 'mean' default is
    // right for a score and meaningless for a timestamp: the mean of 09:00, 09:05 and 09:10
    // is a number that denotes nothing anybody asked about. R gets this for free because its
    // single `unused_fn` default IS `first`; a type-aware aggregator has to say it out loud.
    const agg: NumericAgg = ci === timeI ? 'first' : numericAgg;
    let nVary = 0;
    seqRowIndices.forEach((idxs) => {
      // RAW — blanks included. `aggregate` needs to see them: a positional aggregator must be
      // able to return one, and a summary aggregator must be able to skip it. Filtering here
      // took that choice away and made `first` silently mean "first non-missing".
      const vals = idxs.map((i) => cell(rows[i]!, ci));
      if (new Set(vals.filter((v) => v !== '')).size > 1) nVary++;
      perCol[c]!.push(aggregate(vals, agg, categoricalAgg));
    });
    // Time obviously varies within a session — that is what a session IS. Reporting it as a
    // surprise would bury the columns that vary and should not.
    if (nVary > 0 && ci !== timeI) varying.push({ column: headers[ci]!, nSessions: nVary });
  });

  const types: ('numeric' | 'categorical')[] = ['categorical'];             // .session_id
  metaCols.forEach((_ci, c) => types.push(isNumericColumn(perCol[c]!) ? 'numeric' : 'categorical'));
  types.push('numeric');                                                     // .session_nr

  const metaRows: (string | number | null)[][] = ids.map((id, r) => {
    const row: (string | number | null)[] = [id];
    metaCols.forEach((_ci, c) => {
      const v = perCol[c]![r]!;
      row.push(types[c + 1] === 'numeric' ? (v === '' ? null : Number(v)) : (v === '' ? null : v));
    });
    row.push(sessionNr[r]!);
    return row;
  });

  const lens = sequences.map((s) => s.length);
  const totalActions = lens.reduce((a, b) => a + b, 0);

  return {
    sequences,
    ids,
    actors,
    sessionNr,
    seqRowIndices,
    times,
    meta: { columns, rows: metaRows, types, varying },
    statistics: {
      totalSessions: ids.length,
      totalActions,
      maxSequenceLength: lens.length ? Math.max(...lens) : 0,
      meanSequenceLength: lens.length ? totalActions / lens.length : 0,
      uniqueActors: actorOrder.length,
      sessionsPerActor: actorOrder.map((a) => ({
        actor: a,
        nSessions: actors.filter((x) => x === a).length,
      })),
      actionsPerSession: ids.map((id, i) => ({ id, nActions: lens[i]! })),
      sessionsFromGap,
    },
  };
}

// ---------------------------------------------------------------------------
// designMatrix — R's model.matrix, so a FACTOR can enter a covariate model
// ---------------------------------------------------------------------------

export interface DesignMatrix {
  /** n x p, WITHOUT an intercept column (mmm adds one). */
  X: number[][];
  /** One name per column of X. A dummy is named `col=level`. */
  names: string[];
  /** The dropped reference level of each factor — the baseline every dummy is read against. */
  reference: Record<string, string>;
  /** Sessions dropped because a term was missing for them, by id. A hole in X cannot be
   *  imputed to 0: that silently places the case at the covariate's origin. */
  dropped: number[];
}

/**
 * Build a design matrix from selected metadata columns.
 *
 * A numeric column enters as itself. A FACTOR with L levels enters as L−1 dummies against a
 * dropped reference level — R's `model.matrix`, and the reason `nnet::multinom` and
 * `seqHMM::build_mmm(formula = ~ condition)` accept factors without the caller thinking about
 * it. carmnote could not: it required numeric covariates, so `condition` simply could not be
 * modelled. Ordinal-encoding it as 1, 2, 3 instead would have produced a slope that looks like
 * a result and means nothing.
 */
export function designMatrix(
  meta: MetaData,
  terms: readonly string[],
  options?: { reference?: Record<string, string> },
): DesignMatrix {
  const idxOf = (t: string) => meta.columns.indexOf(t);
  const names: string[] = [];
  const reference: Record<string, string> = {};
  const cols: (number | null)[][] = [];      // each entry: one column of X, per session

  for (const t of terms) {
    const ci = idxOf(t);
    if (ci < 0) throw new Error(`designMatrix: no metadata column named "${t}"`);
    const vals = meta.rows.map((r) => r[ci]);

    if (meta.types[ci] === 'numeric') {
      names.push(t);
      cols.push(vals.map((v) => (v == null ? null : Number(v))));
      continue;
    }
    const levels = Array.from(new Set(vals.filter((v) => v != null).map(String))).sort();
    if (levels.length < 2) throw new Error(`designMatrix: "${t}" has fewer than 2 levels — it is a constant, not a covariate`);
    const ref = options?.reference?.[t] ?? levels[0]!;
    if (!levels.includes(ref)) throw new Error(`designMatrix: reference level "${ref}" not found in "${t}"`);
    reference[t] = ref;
    for (const L of levels) {
      if (L === ref) continue;
      names.push(t + '=' + L);
      cols.push(vals.map((v) => (v == null ? null : (String(v) === L ? 1 : 0))));
    }
  }

  const dropped: number[] = [];
  const X: number[][] = [];
  for (let r = 0; r < meta.rows.length; r++) {
    const row = cols.map((c) => c[r]!);
    if (row.some((v) => v == null || !Number.isFinite(v))) { dropped.push(r); continue; }
    X.push(row as number[]);
  }
  return { X, names, reference, dropped };
}
